// runOnceForAllItems: flatten every per-category fetch into one item per entry,
// each carrying the full message list for the scorer.
//
// Input is one item per scanned category: { total, entries: [...] }. /v1/entries
// returns an object, so the HTTP node does NOT split it into separate items.
//
// 2026-09-27: rubric rewritten for a MORNING NEWS brief. The old prompt asked
// "would a senior infrastructure engineer want this", so the model dutifully
// filled the brief with Kubernetes point releases and llama.cpp tags and left out
// the day's actual tech and AI news. News value now leads; Deep's specialities are
// a bonus on top, not the test.
const seen = new Set();
const entries = [];
$input.all().forEach((item) => {
  const arr = (item.json && Array.isArray(item.json.entries)) ? item.json.entries : [];
  arr.forEach((e) => {
    if (e && e.id && !seen.has(e.id)) { seen.add(e.id); entries.push(e); }
  });
});

// Newest first: this is a morning news brief, recency is part of the value.
entries.sort((a, b) => new Date(b.published_at || 0) - new Date(a.published_at || 0));
const MAX_PER_RUN = 100;
const batch = entries.slice(0, MAX_PER_RUN);
console.log('fetched ' + entries.length + ' unread across categories, scoring ' + batch.length);

// Commerce stays code-classified (2026-09-16); kept as defence in depth even
// though deal categories are no longer scanned by this workflow.
const COMMERCE_SOURCE = /deal|slickdeal|coupon|bargain|woot|frugal|shopping|clearance/i;
const PRICE = /\$\s?\d|\b\d+\s?%\s*off\b/i;
const RETAIL_CUE = /free ship|free s&h|\bfs\b|coupon|promo code|w\/ ?(?:s&s|code|prime)|subscribe & save|prime member|at amazon|clearance|\bsale\b|\bdeal\b/i;
function isCommerce(category, feed, title) {
  if (COMMERCE_SOURCE.test(category) || COMMERCE_SOURCE.test(feed)) return true;
  return PRICE.test(title) && RETAIL_CUE.test(title);
}

const SYS = [
  "You triage articles for Deep's MORNING TECH NEWS BRIEF. He reads it at 07:00 as his main tech news source. He wants to know what actually happened in tech, what moved in AI and in the tech industry, and only then anything deep in his own speciality.",
  '',
  'Reply with ONE JSON object and nothing else:',
  '{"score": <integer 0-10>, "bucket": "<one word>", "why": "<max 20 words>", "publish_angle": "<post title or empty string>"}',
  '',
  'score = how much this belongs in a morning tech news brief:',
  "9-10 today's big story: major launch, major outage or breach, big funding / M&A / earnings surprise, a model release the industry will discuss",
  '7-8  clearly newsworthy: notable release, real incident, significant industry or market move, strong Hacker News discussion, sharp analysis',
  '5-6  worth knowing: minor release, decent analysis, niche but real technical writeup',
  '2-4  routine: incremental announcement, vendor marketing, listicle, low-stakes update',
  '0-1  not news: shopping, entertainment, lifestyle, clickbait',
  '',
  'WEIGHTING',
  '- General tech news and AI news outrank niche infrastructure detail. A Kubernetes point release or a llama.cpp build tag is a 5, not an 8.',
  '- Money and industry moves are news: funding rounds, acquisitions, earnings, layoffs, antitrust, big partnerships.',
  "- Deep's specialities (object storage and S3, Kubernetes, LLM inference infra, homelab) are a BONUS on top of news value, never a substitute for it.",
  '',
  'bucket must be exactly one of these lowercase words:',
  'news business ai security infra storage homelab career noise',
  '  news      general tech news, launches, outages, policy, regulation',
  '  business  funding, M&A, earnings, markets, layoffs, company strategy',
  '  ai        models, labs, AI research and releases, AI tooling',
  '  security  CVEs, breaches, exploits, incident writeups',
  '  infra     kubernetes, cloud, databases, distributed systems, SRE',
  '  storage   object storage and S3, data platforms, backup',
  '  homelab   self-hosting, homelab hardware, Proxmox and Talos',
  '  career    hiring, comp, role and industry shifts for engineers',
  '  noise     not news at all',
  '',
  'HARD RULES',
  '- Shopping deals, coupons, discounts, product prices, retail listings: score 0, bucket noise, publish_angle "".',
  '- Entertainment, sport, celebrity or non-tech politics: score 0-2.',
  '- "why" describes THE ARTICLE IN FRONT OF YOU. Never copy these instructions, the bucket list or the score bands into "why".',
  '- If you cannot tell what the article is about, use its title as "why" and score 2.',
].join('\n');

// Worked examples as real turns. These four encode the correction: retail is 0,
// money news is high, niche infra is mid, a model launch is top.
const SHOTS = [
  [
    'TITLE: Nike Men\'s Club Fleece Hoodie (2 Colors) $24.99 + Free Shipping $75+\nFEED: Slickdeals Popular Deals RSS Feed\nMINIFLUX_CATEGORY: Deals\n\nEXCERPT:\nNike Club Fleece Hoodie available in two colors for $24.99 with free shipping over $75.',
    '{"score": 0, "bucket": "noise", "why": "Retail clothing sale, no news value.", "publish_angle": ""}',
  ],
  [
    'TITLE: Nvidia beats on earnings but warns data-centre growth will slow\nFEED: Bloomberg Technology\nMINIFLUX_CATEGORY: Tech-Business\n\nEXCERPT:\nNvidia reported quarterly revenue above estimates while guiding to slower data-centre growth next year, sending shares down 4% after hours.',
    '{"score": 9, "bucket": "business", "why": "Nvidia beat estimates but guided to slower data-centre growth; shares fell 4% after hours.", "publish_angle": "What Nvidia guidance says about the AI capex cycle"}',
  ],
  [
    'TITLE: Kubernetes v1.34.3 patch release\nFEED: Kubernetes Blog\nMINIFLUX_CATEGORY: Cloud-DevOps\n\nEXCERPT:\nThis patch release contains bug fixes for kubelet and the scheduler, plus dependency bumps.',
    '{"score": 5, "bucket": "infra", "why": "Routine Kubernetes patch release with kubelet and scheduler bug fixes.", "publish_angle": ""}',
  ],
  [
    'TITLE: OpenAI launches GPT-6 with native computer use\nFEED: OpenAI News\nMINIFLUX_CATEGORY: AI-News\n\nEXCERPT:\nOpenAI announced GPT-6, adding native computer control and a 1M token context window, available to API customers today.',
    '{"score": 10, "bucket": "ai", "why": "OpenAI ships GPT-6 with native computer use and 1M token context, API available today.", "publish_angle": "What native computer use changes for agent design"}',
  ],
];

const shotMessages = SHOTS.flatMap(([u, a]) => [
  { role: 'user', content: u },
  { role: 'assistant', content: a },
]);

return batch.map((e) => {
  const html = e.content || e.summary || '';
  const text = String(html).replace(/<[^>]+>/g, ' ').replace(/&[a-z]+;/gi, ' ').replace(/\s+/g, ' ').trim().slice(0, 1400);
  const feed = (e.feed && e.feed.title) || '';
  const category = (e.feed && e.feed.category && e.feed.category.title) || '';
  const title = e.title || '';
  const commerce = isCommerce(category, feed, title);
  const userMsg = `TITLE: ${title}\nFEED: ${feed}\nMINIFLUX_CATEGORY: ${category}\nAUTHOR: ${e.author || ''}\nURL: ${e.url}\nPUBLISHED: ${e.published_at || ''}\n\nEXCERPT:\n${text || '(no excerpt)'}`;
  return {
    json: {
      id: e.id,
      title,
      url: e.url,
      feed,
      category,
      published_at: e.published_at || '',
      isCommerce: commerce,
      sysPrompt: SYS,
      userMsg,
      messages: [{ role: 'system', content: SYS }, ...shotMessages, { role: 'user', content: userMsg }],
    },
  };
});

// runOnceForEachItem
// $json = raw Ollama /api/chat response for ONE entry.
// Original entry fields come from Prep entries via pairedItem, so a batched /
// retried / dropped Ollama call can never pair a verdict with the wrong article.
const src = $('Prep entries').item.json;   // { id, title, url, feed, category, isCommerce, ... }
const res = $json;                          // { model, message: { content }, ... }

let v = {};
try { v = JSON.parse((res.message && res.message.content) || '{}'); }
catch (e) { v = { score: 0, bucket: 'noise', why: 'model returned non-JSON', publish_angle: '' }; }

const entryId = Number(src.id);
const hasId = Number.isFinite(entryId);

let score = Math.round(Number(v.score));
if (!Number.isFinite(score)) score = 0;
score = Math.max(0, Math.min(10, score));

// Buckets are a fixed list; anything else is noise rather than a new bucket.
// 'business' added 2026-09-27 for funding / M&A / earnings / market moves.
const BUCKETS = ['news', 'business', 'ai', 'security', 'infra', 'storage', 'homelab', 'career', 'noise'];
let bucket = String(v.bucket || '').trim().toLowerCase();
if (!BUCKETS.includes(bucket)) bucket = 'noise';

let why = String(v.why || '').slice(0, 240);
const angle = String(v.publish_angle || '').slice(0, 240);

// Rubric echo guard: when the model pastes the prompt's own wording into "why"
// it has not read the article, and its score means nothing.
const RUBRIC_ECHO = /covers security, cves|cves, breaches, exploits|incident writeups, hardening|kubernetes, cloud, databases|llms, (?:inference, )?agents|self-hosting, (?:homelab hardware|proxmox)|object storage (?:and|\/) s3|funding, m&a, earnings|general tech news, launches/i;
const echoed = RUBRIC_ECHO.test(why);
if (echoed) {
  score = Math.min(score, 4);
  why = `[unverified] ${why}`.slice(0, 240);
}

// Commerce is classified deterministically in Prep entries. The model gets no
// vote: a deal must never be starred, notified or written into curator_items.
const isCommerce = !!src.isCommerce;
if (isCommerce) {
  score = 0;
  bucket = 'noise';
  if (!why) why = 'Retail deal (classified by feed/category, not scored).';
}

let action = score >= 7 ? 'notify' : (score >= 5 ? 'star' : 'skip');

const isManual = !!($execution && $execution.mode === 'manual');
const now = DateTime.now().setZone('America/Chicago');
const hm = now.hour + now.minute / 60;
const quiet = (hm >= 22 || hm < 7.5);

const sd = $getWorkflowStaticData('global');
const today = now.toFormat('yyyy-LL-dd');
if (sd.capDate !== today) { sd.capDate = today; sd.capCount = 0; }
const DAILY_CAP = 8;

const wasNotify = action === 'notify';
if (action === 'notify' && !isManual) {
  if (quiet || (sd.capCount || 0) >= DAILY_CAP) action = 'star';
  else sd.capCount = (sd.capCount || 0) + 1;
}

if (!hasId) action = 'skip';

const emoji = ({
  news: '📰', business: '💵', ai: '🤖', security: '🔒',
  infra: '⚙️', storage: '🗄️', homelab: '🏠', career: '🎯', noise: '·',
})[bucket] || '•';

const gotifyPriority = score >= 9 ? 8 : 6;
const gotifyTitle = `${emoji} [${score}] ${src.feed || ''}`.slice(0, 120);
let gotifyMessage = `**${src.title}**\n\n${why}`;
if (angle && !isCommerce) gotifyMessage += `\n\n✍️ Post angle: ${angle}`;
gotifyMessage += `\n\n${src.url}`;

return {
  json: {
    id: entryId, entryId,
    url: src.url, title: src.title, feed: src.feed, category: src.category,
    score, bucket, why, publish_angle: angle,
    action, wasNotify, isCommerce, echoed,
    gotifyPriority, gotifyTitle, gotifyMessage,
  },
};

// One item per Miniflux category to scan.
//
// 2026-09-27: the old single fetch was status=unread&direction=asc&limit=60 -
// OLDEST first - against a backlog that is 73% Slickdeals (4,800 unread, ~407
// new/day vs a 360/day scan budget). Deals could never drain, so the curator
// chewed stale retail while actual news never entered the window. That, not the
// prompt, is why the brief read as niche.
//
// Deals and Firehose are scanned by miniflux-deals-router instead; this node only
// plans real editorial categories, newest-first.
const EXCLUDE = /deal|slickdeal|firehose/i;
const cats = $input.all()
  .map((i) => i.json)
  .filter((c) => c && c.id && c.title && !EXCLUDE.test(c.title));

// Per-category budget: news sources get room, slow blogs need very little.
const BUDGET = {
  'Tech-News': 14,
  'Tech-Business': 12,
  'AI-News': 10,
  'HN-Trending': 10,
  'Digests': 8,
  'Applied-AI-Agents': 8,
  'Cloud-DevOps': 8,
  'AI-Infra-Inference': 6,
  'Object-Storage-Data': 5,
  'Homelab-K8s': 5,
  'Career-FDE': 4,
  'Security-SRE': 4,
};

const plan = cats.map((c) => ({
  json: { category_id: c.id, category_title: c.title, limit: BUDGET[c.title] || 4 },
}));
console.log('scanning ' + plan.length + ' categories, budget ' + plan.reduce((n, p) => n + p.json.limit, 0) + ' entries');
return plan;
